//! 🧭️ Numeric original-member lookup performs one source byte or one immutable table probe per funded turn.
use super::{ChildEditorRead,ChildContentView,MemberKeyRef};
use crate::AppOperationContext;
use semio_framework_value::{ValueError,ValueRefusalKind,RetirementDemand,retained_clone::{RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,retained_clone_grant_admits}};
use crate::child_view::{CHILD_CONTENT_SLOTS,CHILD_CONTENT_ID_BYTES};
#[derive(Clone,Copy)]pub enum OriginalChildMemberOperation<'a>{Command(&'a AppOperationContext),Render{operation:&'a crate::AppRenderOperationContext,parent_document_id:&'a str}}
#[derive(Clone,Copy,PartialEq,Eq)]enum OperationIdentity{Command{operation:u64,generation:u64,instance:u32},Render{revision:u64,generation:u64,instance:u32}}
impl<'a> OriginalChildMemberOperation<'a>{pub fn from_view<P>(view:&'a crate::ArtifactView<'_,P>)->Result<Self,ValueError>{if let Some(operation)=view.operation_optional(){if view.parent_document_id().is_some_and(|parent|parent!=operation.parent_document_id){return Err(refusal("original member read parent differs from its command operation"))}return Ok(Self::Command(operation))}let operation=view.render_operation_ref().ok_or_else(||refusal("original member read requires its actual render or command operation"))?;let parent_document_id=view.parent_document_id().ok_or_else(||refusal("original render member read has no real parent artifact identity"))?;Ok(Self::Render{operation,parent_document_id})}fn identity(self)->OperationIdentity{match self{Self::Command(operation)=>OperationIdentity::Command{operation:operation.operation_id,generation:operation.generation,instance:operation.app_instance_id},Self::Render{operation,..}=>OperationIdentity::Render{revision:operation.base_revision.0,generation:operation.generation.0,instance:operation.app_instance_id}}}fn parent(self)->&'a str{match self{Self::Command(operation)=>&operation.parent_document_id,Self::Render{parent_document_id,..}=>parent_document_id}}fn revision(self)->&'a[u8;32]{match self{Self::Command(operation)=>&operation.canonical_base_revision,Self::Render{operation,..}=>&operation.canonical_base_revision}}}
#[derive(Clone,Copy,PartialEq,Eq)]enum Phase{Bind,Hash,Probe,Equal,Ready,Closed}
pub struct OriginalChildMemberLookup{source:Option<(u64,usize,usize,usize)>,root:usize,keys:[(usize,usize);3],operation:Option<OperationIdentity>,parent_document:(usize,usize),revision:[u8;32],phase:Phase,field:usize,offset:usize,probe:usize,hash:u64,entry:usize,closing:bool}
pub struct OriginalChildMemberReadAdvance<'a,S>{pub progress:RetainedCloneProgress,pub read:Option<ChildEditorRead<'a,S>>}
fn refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
impl OriginalChildMemberLookup{
 const HEADER:usize=2*std::mem::size_of::<Self>();
 pub fn birth_demand()->RetirementDemand{RetirementDemand{copy_bytes:Self::HEADER,depth:1,..Default::default()}}
 pub fn admit(g:RetainedCloneGrant)->Result<(Self,RetainedCloneProgress),ValueError>{let d=Self::birth_demand();if !retained_clone_grant_admits(g,d){return Err(refusal("original member lookup birth is unfunded"))}Ok((Self{source:None,root:0,keys:[(0,0);3],operation:None,parent_document:(0,0),revision:[0;32],phase:Phase::Bind,field:0,offset:0,probe:0,hash:0xcbf29ce484222325,entry:0,closing:false},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 pub fn demand<S:'static>(&self)->RetirementDemand{RetirementDemand{copy_bytes:Self::HEADER+2*std::mem::size_of::<OriginalChildMemberReadAdvance<'static,S>>(),depth:1,..Default::default()}}
 fn parts(key:MemberKeyRef<'_>)->[&str;3]{[key.owner,key.slot,key.child_id]}
 fn root(view:&ChildContentView)->usize{view.root.as_ref().map_or(0,|root|std::sync::Arc::as_ptr(root)as usize)}
 fn verify<P:Send+Sync+'static>(&self,parent:RetainedCloneRef<'_,P>,children:&ChildContentView,key:MemberKeyRef<'_>,operation:OriginalChildMemberOperation<'_>)->Result<(),ValueError>{if self.closing||self.phase==Phase::Closed{return Err(refusal("original member lookup is closing"))}if let Some(source)=self.source{let keys=Self::parts(key).map(|text|(text.as_ptr()as usize,text.len()));if source!=parent.reference_identity()||self.root!=Self::root(children)||self.keys!=keys||self.operation!=Some(operation.identity())||self.parent_document!=(operation.parent().as_ptr()as usize,operation.parent().len())||self.revision!=*operation.revision(){return Err(refusal("original member lookup source or key changed"))}}Ok(())}
 pub fn next_operation_demand<S:'static,P:Send+Sync+'static>(&self,parent:RetainedCloneRef<'_,P>,children:&ChildContentView,key:MemberKeyRef<'_>,operation:OriginalChildMemberOperation<'_>)->Result<RetirementDemand,ValueError>{self.verify(parent,children,key,operation)?;Ok(self.demand::<S>())}
 fn next_probe(&mut self){self.probe+=1;self.field=0;self.offset=0;self.phase=Phase::Probe}
 pub fn advance_operation<'a,S:Send+Sync+'static,P:Send+Sync+'static>(&mut self,parent:RetainedCloneRef<'_,P>,children:&'a ChildContentView,key:MemberKeyRef<'_>,operation:OriginalChildMemberOperation<'a>,g:RetainedCloneGrant)->Result<OriginalChildMemberReadAdvance<'a,S>,ValueError>{let d=self.next_operation_demand::<S,P>(parent,children,key,operation)?;if !retained_clone_grant_admits(g,d){return Ok(OriginalChildMemberReadAdvance{progress:Default::default(),read:None})}let progress=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};let fail=|message|refusal(message).with_retained_progress(progress);let parts=Self::parts(key);
 match self.phase{Phase::Bind=>{if parts.iter().any(|text|text.len()>CHILD_CONTENT_ID_BYTES){return Err(fail("original member key exceeds its fixed source bound"))}self.source=Some(parent.reference_identity());self.root=Self::root(children);self.keys=parts.map(|text|(text.as_ptr()as usize,text.len()));self.operation=Some(operation.identity());self.parent_document=(operation.parent().as_ptr()as usize,operation.parent().len());self.revision=*operation.revision();self.phase=Phase::Hash;},Phase::Hash=>{let text=parts[self.field];if self.offset<text.len(){self.hash=(self.hash^u64::from(text.as_bytes()[self.offset])).wrapping_mul(0x100000001b3);self.offset+=1;}else{if self.field==1||self.field==0&&!text.is_empty(){self.hash=(self.hash^if self.field==0{0xfe}else{0xff}).wrapping_mul(0x100000001b3)}self.field+=1;self.offset=0;if self.field==3{self.field=0;self.phase=Phase::Probe}}},Phase::Probe=>{if self.probe==CHILD_CONTENT_SLOTS{return Err(fail("original member lookup exhausted its immutable table"))}let root=children.root.as_deref().ok_or_else(||fail("original child read has no live member root"))?;let index=(self.hash as usize%CHILD_CONTENT_SLOTS+self.probe)%CHILD_CONTENT_SLOTS;let entry=ChildContentView::entry_at(root,index).ok_or_else(||fail("original child read has no matching live member"))?;self.entry=std::sync::Arc::as_ptr(entry)as usize;self.phase=Phase::Equal;},Phase::Equal|Phase::Ready=>{let root=children.root.as_deref().ok_or_else(||fail("original child root changed"))?;let index=(self.hash as usize%CHILD_CONTENT_SLOTS+self.probe)%CHILD_CONTENT_SLOTS;let entry=ChildContentView::entry_at(root,index).ok_or_else(||fail("original child entry disappeared"))?;if self.entry!=std::sync::Arc::as_ptr(entry)as usize{return Err(fail("original child entry identity changed"))}if self.phase==Phase::Ready{let read=entry.snapshot.typed::<S>().ok_or_else(||fail("original child snapshot type differs from its registered capability"))?;return Ok(OriginalChildMemberReadAdvance{progress,read:Some(ChildEditorRead{read,entry,parent_identity:parent.reference_identity().2,parent_artifact:operation.parent(),parent_revision:operation.revision()})})}let current=[entry.owner.as_str(),entry.slot.as_str(),entry.child_id.as_str()][self.field];let expected=parts[self.field];if current.len()!=expected.len(){self.next_probe()}else if self.offset==current.len(){self.offset=0;self.field+=1;if self.field==3{self.phase=Phase::Ready}}else if current.as_bytes()[self.offset]!=expected.as_bytes()[self.offset]{self.next_probe()}else{self.offset+=1}},Phase::Closed=>unreachable!()}Ok(OriginalChildMemberReadAdvance{progress,read:None})}

 pub fn next_demand<S:'static,P:Send+Sync+'static>(&self,parent:RetainedCloneRef<'_,P>,children:&ChildContentView,key:MemberKeyRef<'_>,operation:&AppOperationContext)->Result<RetirementDemand,ValueError>{self.next_operation_demand::<S,P>(parent,children,key,OriginalChildMemberOperation::Command(operation))}
 pub fn advance<'a,S:Send+Sync+'static,P:Send+Sync+'static>(&mut self,parent:RetainedCloneRef<'_,P>,children:&'a ChildContentView,key:MemberKeyRef<'_>,operation:&'a AppOperationContext,g:RetainedCloneGrant)->Result<OriginalChildMemberReadAdvance<'a,S>,ValueError>{self.advance_operation(parent,children,key,OriginalChildMemberOperation::Command(operation),g)}
 pub fn begin_close(&mut self){self.closing=true}
 pub fn close_demand(&self)->RetirementDemand{if self.phase==Phase::Closed{Default::default()}else{Self::birth_demand()}}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{if !self.closing{return Err(refusal("original member lookup closure has not begun"))}if self.phase==Phase::Closed||!retained_clone_grant_admits(g,self.close_demand()){return Ok(Default::default())}self.source=None;self.root=0;self.keys=[(0,0);3];self.entry=0;self.phase=Phase::Closed;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:Self::HEADER,..Default::default()})}
 pub fn terminal_is_empty(&self)->bool{self.phase==Phase::Closed&&self.source.is_none()&&self.root==0&&self.entry==0}
}
#[cfg(test)]#[path="🧪️tests.rs"]mod tests;

struct LookupRetirement{cursor:Option<OriginalChildMemberLookup>}
impl semio_framework_value::retirement::RetireOwned for OriginalChildMemberLookup{fn retirement(self)->Box<dyn semio_framework_value::retirement::RetirementCursor>{Box::new(LookupRetirement{cursor:Some(self)})}fn retirement_birth_bytes(&self)->Option<usize>{Some(std::mem::size_of::<LookupRetirement>())}fn controlled_retirement_supported()->bool{true}}
impl semio_framework_value::retirement::RetirementCursor for LookupRetirement{fn next_demand(&self,_:usize)->Result<RetirementDemand,ValueError>{let Some(cursor)=self.cursor.as_ref()else{return Ok(Default::default())};let d=cursor.close_demand();Ok(RetirementDemand{copy_bytes:d.copy_bytes.checked_add(2*std::mem::size_of::<Self>()).ok_or_else(||refusal("original member lookup retirement copy extent overflow"))?,depth:d.depth.checked_add(1).ok_or_else(||refusal("original member lookup retirement depth overflow"))?,..d})}fn close_step(&mut self,g:RetainedCloneGrant)->semio_framework_value::retirement::RetirementStep{use semio_framework_value::retirement::RetirementStep;let d=match self.next_demand(g.maximum_copy_bytes){Ok(d)=>d,Err(error)=>return RetirementStep::Failure(error)};if self.cursor.is_none(){return RetirementStep::Complete}if !retained_clone_grant_admits(g,d){return RetirementStep::BudgetExhausted}let own=2*std::mem::size_of::<Self>();let cursor=self.cursor.as_mut().unwrap();cursor.begin_close();match cursor.close_step(RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-own,maximum_depth:g.maximum_depth-1,..g}){Ok(mut p)=>{if cursor.terminal_is_empty(){self.cursor=None}p.copied_items=p.copied_items.max(1);p.copied_bytes+=own;RetirementStep::Progress(p)},Err(error)=>{let mut p=error.retained_progress();p.copied_items=p.copied_items.max(1);p.copied_bytes+=own;RetirementStep::Failure(error.with_retained_progress(p))}}}fn terminal_is_empty(&self)->bool{self.cursor.is_none()}fn terminal_release_bytes(&self)->Option<usize>{self.terminal_is_empty().then_some(std::mem::size_of::<Self>())}}
